<template><aside class="performance-panel" data-testid="performance-panel"><b>Performance</b><span>FPS {{metrics.fps.toFixed(1)}}</span><span>Frame {{metrics.frameMs.toFixed(2)}} ms</span><span>FK {{metrics.fkMs.toFixed(3)}} ms</span><span>Render {{metrics.renderMs.toFixed(2)}} ms</span><span>Draw {{metrics.drawCalls}}</span><span>Triangles {{metrics.triangles}}</span><span>Pending {{metrics.pendingJointUpdates}}</span><span>Commits {{metrics.backendCommits}}</span><span>Rebuilds {{metrics.sceneRebuilds}}</span><span>Mesh loads {{metrics.meshLoads}}</span></aside></template><script setup lang="ts">import {onBeforeUnmount,reactive} from 'vue';import {performanceMetrics,type MetricsSnapshot} from '@/runtime/PerformanceMetrics';const metrics=reactive<MetricsSnapshot>(performanceMetrics.snapshot());const timer=setInterval(()=>Object.assign(metrics,performanceMetrics.snapshot()),250);onBeforeUnmount(()=>clearInterval(timer))</script><style scoped>.performance-panel{position:absolute;z-index:3;right:12px;top:48px;display:grid;grid-template-columns:1fr 1fr;gap:3px 12px;padding:9px;background:#0a121be6;border:1px solid #35536b;border-radius:5px;color:#91b4ca;font:11px Consolas}.performance-panel b{grid-column:1/-1;color:#47b9f0}</style>
